## 주요 고민과 해결 과정
1. 기존의 페이지당 해당 페이지를 위한 utils 가 너무 컸다. -> 한 군데에서 해당 코드를 모두 관리하는 것은 좋지 않다고 파악하여 각 컴포넌트로 분리하였고 해당 컴포넌트에 맞게끔 rendering 및 util 파일들을 분리하였다. 

3. SPA 방식을 채택하다보니까, 페이지 전환 시, HTML/CSS/JS 를 제거하고 교체하는 잠깐사이에 깜빡임이 있었다. (네트워크 상태가 좋지 않은 경우엔 해당 상황에 너무 UX 가 좋지 않다고 판단함) -> loading 컴포넌트를 구현 및 적용하여 페이지 전환시 해당 컴포넌트를 먼저 보여주고 요청 시작하는 것으로 해결함.
```js

// 탭 전환 함수
async function switchTab(tabName) {
  const bodyContainer = document.getElementById("body-container");

  // 기존 페이지별 CSS 제거
  removePageCSS();

  // 로딩 상태 표시
  bodyContainer.innerHTML = await renderLoading();

  try {
    switch (tabName) {
      case "MAIN_VIEW":
        // 모든 리소스가 완전히 로드된 후 렌더링
        await Promise.all([
          loadScript("src/pages/main/main.js"),
          loadCSS("src/pages/main/main.css"),
        ]);
        // 메인 페이지 렌더링 함수 호출
        bodyContainer.innerHTML = await renderMain();
        initMain();
        break;

      case "CALENDAR_VIEW":
        // 모든 리소스가 완전히 로드된 후 렌더링
        await Promise.all([
          loadScript("src/pages/calendar/calendar.js"),
          loadCSS("src/pages/calendar/calendar.css"),
        ]);
        // 달력 페이지 렌더링 함수 호출
        bodyContainer.innerHTML = await renderCalendar();
        initCalendar();
        break;

      case "STATISTIC_VIEW":
        // 모든 리소스가 완전히 로드된 후 렌더링
        await Promise.all([
          loadScript("src/pages/statistic/statistic.js"),
          loadCSS("src/pages/statistic/statistic.css"),
        ]);
        // 통계 페이지 렌더링 함수 호출
        bodyContainer.innerHTML = await renderStatistic();
        initStatistic();
        break;
    }
  } catch (error) {
    console.error("Error switching tab:", error);
    bodyContainer.innerHTML = `<p>페이지를 로드할 수 없습니다.</p>`;
  }
}
```

4. 도넛 차트 내 조각을 호버링 할 때마다 움직이는 에니메이팅을 넣고싶었음. -> 해당 조각마다 관리하기 위해서는 canvas가 아니라 svg 로 각 DOM 요소들을 만들고 이를  관리했어야 했음. 따라서 canvas의 arc 함수내에 필요한 params를 그대로 이용하고, 해당 params를 그대로 사용하되, svg 형식으로 나오는 함수를 만들고 이를 하나씩 이전함. 그 위에 css 를 넣음으로써 적용했음.
```js
  // 기존 canvas 의 arc 함수를 svg path 형식으로 변환하는 함수
  function describeArc(cx, cy, rOuter, rInner, startAngle, endAngle) {
    const polarToCartesian = (cx, cy, r, angle) => [
      cx + r * Math.cos(angle),
      cy + r * Math.sin(angle),
    ];
    const [x1, y1] = polarToCartesian(cx, cy, rOuter, startAngle);
    const [x2, y2] = polarToCartesian(cx, cy, rOuter, endAngle);
    const [x3, y3] = polarToCartesian(cx, cy, rInner, endAngle);
    const [x4, y4] = polarToCartesian(cx, cy, rInner, startAngle);
    const largeArcFlag = endAngle - startAngle > Math.PI ? 1 : 0;

    return [
      `M ${x1} ${y1}`,
      `A ${rOuter} ${rOuter} 0 ${largeArcFlag} 1 ${x2} ${y2}`,
      `L ${x3} ${y3}`,
      `A ${rInner} ${rInner} 0 ${largeArcFlag} 0 ${x4} ${y4}`,
      "Z",
    ].join(" ");
  }

```


5. 기존에 사용하던 HistroyList(가계부 리스트를) 통계 페이지 내에서 랜더링 했어야 했음 -> 기존의 메인 페이지에서 해당 HistroyList를 불러오던 함수와 필터링 함수를 확장성 있게 개선하여 해당 함수들을 이용해서 새로운 코드를 짜는 것이 아니라 재활용함.

```js

// 확장 가능한 필터링 함수 (필터링 조건을 파라미터로 받음)
export function getFilteredDataWithCondition(
  initialData,
  filterCondition = null
) {
  return initialData.filter((item) => {
    const itemDate = new Date(item.date);
    const isCurrentMonth =
      itemDate.getFullYear() === dateStore.getState().currentYear &&
      itemDate.getMonth() === dateStore.getState().currentMonth - 1;

    // 기본 월 필터링
    if (!isCurrentMonth) return false;

    // 추가 필터링 조건이 있으면 적용
    if (filterCondition) {
      return filterCondition(item);
    }

    return true;
  });
}
```

