The following are the recipes I tested:
```js
ServerEvents.recipes(event => {
    // Polarizing  (Input (max 1), Output (max 1), Energy)
    event.recipes.tfmg.polarizing("minecraft:dirt", "minecraft:mud", 400)

    // Distillation (Input (max 1), Output (max 6))
    event.recipes.tfmg.distillation(Fluid.of("minecraft:water", 500), [Fluid.of("minecraft:water", 400), Fluid.of("minecraft:lava", 100)])

    // Vat (Input (max 4), Output (max 4))
    event.recipes.tfmg.vat_machine_recipe('minecraft:dirt', 'minecraft:mud')
        .machines("tfmg:mixing") // Valid Machines
        .allowedVatTypes("tfmg:steel_vat", "tfmg:cast_iron_vat") // Valid Vat Types
        .heated() // Heat Requirement
        .processingTime(200) // Processing Time
        .minSize(1) // Minimum Size

    // Coking (Input (max 1), Output (max 1 (item), 2 (fluid)), Processing Time)
    event.recipes.tfmg.coking("minecraft:mud", ["minecraft:dirt", Fluid.of("minecraft:water", 5)], 100)

    // Industrial Blasting (Input (max 2), Output (max 3), Processing Time)
    event.recipes.tfmg.industrial_blasting("minecraft:dirt", [Fluid.of("minecraft:water", 300), Fluid.of("minecraft:lava", 200)], 1)

    // Casting (Input (max 1), Output (max 1), Processing Time)
    event.recipes.tfmg.casting(Fluid.of("minecraft:lava", 1), "minecraft:cobblestone", 100)

    // Hot Blasting (Input (max 2), Output (max 2), Processing Time)
    event.recipes.tfmg.hot_blast([Fluid.of("minecraft:water", 25), Fluid.of("minecraft:lava", 5)], [Fluid.of("tfmg:hydrogen", 25), Fluid.of("tfmg:carbon_dioxide", 25)], 200)

    // Winding (Input (max 2), Output (max 1), Processing Time) IMPORTANT: 2nd Input is the Spool!
    event.recipes.tfmg.winding(["minecraft:iron_ingot", "tfmg:aluminum_spool"], "minecraft:iron_block", 100)
})
